import{z as s,x as i,o as e,c as C,q as l,j as n,D as B,d as A,s as r,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"SGLang 走读","description":"","frontmatter":{"title":"SGLang 走读","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-sglang-walkthrough.md","filePath":"llm/fw-sglang-walkthrough.md","lastUpdated":1791413859000}'),g={name:"llm/fw-sglang-walkthrough.md"};function d(h,E,p,m,D,T){const t=i("Mermaid");return e(),C("div",null,[E[2]||(E[2]=l('<h1 id="sglang-走读" tabindex="-1">SGLang 走读 <a class="header-anchor" href="#sglang-走读" aria-label="Permalink to &quot;SGLang 走读&quot;">​</a></h1><div class="epigraph"><p>前端把多次生成写成一段程序，运行时就得回答：这些调用共享的 KV 到底放在哪、谁记账。</p><footer>—— 据 Zheng 等，SGLang，NeurIPS 2024 与仓库结构整理</footer></div><p><a href="/llm/fw-vllm-walkthrough">上一课</a>沿一步迭代走完 vLLM 仓库，锚点是「调度输出」这个每步指令集。SGLang 的仓库多出一维：它的出发点是<strong>语言模型程序</strong>——代理、多轮、few-shot 在前端被写成多次 <code>gen</code> 的结构化程序，运行时靠前缀树跨调用复用 KV。程序语义与复用机制已各有课：<a href="/llm/sglang">SGLang 与 RadixAttention</a> 写共设计，<a href="/llm/sglang-radix-tree">前缀树</a>写树怎么长瘦。本课进仓库服务运行时，讲进程分层与数据结构，以仓库当时状态为准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把 vLLM 的读法直接套过来会失手。第一，SGLang 把分词与反分词拆成独立进程：HTTP 进程、调度进程、执行进程组之间走消息总线，如果只在调度器文件里找「一步」，会漏掉请求形态在进程边界上被改写两次。第二，同一条请求在源码里有三个化身——调度视角、执行视角、内核视角各是一个批结构，搜「batch」会命中三套字段相近的类。走读要回答：三个化身各自负责什么、为什么必须分化。</p><h3 id="进程与事件循环" tabindex="-1">进程与事件循环 <a class="header-anchor" href="#进程与事件循环" aria-label="Permalink to &quot;进程与事件循环&quot;">​</a></h3><p>仓库的运行时部分常被称作 srt（SGLang runtime）。HTTP 服务把请求交给分词管理器，后者成批做分词，经消息总线发给每个张量并行组的调度进程。调度进程单线程跑事件循环：收请求、按调度策略从等待队列组新批、把批发给执行器、回读结果再交反分词进程流给客户端。分词被挪出去，是因为它是 CPU 密集的字符串工作，混进调度循环会拉长步时延；这条拆分与 TGI 的 Rust 路由加 Python 推理是同一个直觉，见 <a href="/llm/tgi">TGI</a>。</p><p><span class="marginnote">「张量并行组（TP 组）」翻译一下：把一层的矩阵乘切开到多张卡上同时算，卡间走高速互联。一个 TP 组就是「必须同步算同一层的一组卡」，所以调度按组整体发批，而不是按卡分发——组内任何一张卡慢了，整组都得等它。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沿一步迭代走，锚点落在三个批结构的收窄链上。请求对象持有原始输入、采样参数与前缀树引用，是全生命周期身份。调度器每步把若干请求装进<strong>调度批</strong>：这里做准入——先查前缀树能复用哪些 token 槽，再按缓存感知策略排序，等待队列里的复用机会直接决定谁先上场。调度批发给执行器前被收窄成<strong>执行批</strong>：丢掉 HTTP 与排队元数据，只留执行所需的前缀长度、输出位置与 KV 索引。执行器最后把它翻成<strong>内核批</strong>：张量形状、位置编码、注意力后端的元数据。一层比一层窄，任何一层字段对不上，都会在运行期以形状或索引错误暴露。</p><p>KV 侧是两池一树：请求到 token 槽位的索引池回答「这条请求第 \\(i\\) 个 token 在哪个槽」，token 槽位到 KV 张量的池回答「槽里的键值张量在哪」，前缀树是第三层索引，决定新请求的哪些前缀可以指向旧槽位。注意力后端按注册表选择——FlashInfer、Triton、FlashAttention 等各挂一套实现，由前向模式区分扩展与解码，与 <a href="/llm/flashinfer">FlashInfer</a> 的接口课互为表里。</p><p><span class="marginnote">给个数感受前缀复用的价值：一条 8K token 的系统提示词被 10 个请求共享，不复用要存 \\(10 \\times 8\\text{K}\\) 个槽位；复用后树里只留一份 8K，各请求只在分支处新增自己的几百个 token。KV 显存差出一个数量级，这正是树要「长瘦」的原因。</span></p>',12)),(e(),n(o,null,{default:B(()=>[r(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HTTP%5B%22HTTP%20%E6%9C%8D%E5%8A%A1%22%5D%20--%3E%20TOK%5B%22%E5%88%86%E8%AF%8D%E7%AE%A1%E7%90%86%E5%99%A8%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20TOK%20--%3E%7C%E6%B6%88%E6%81%AF%E6%80%BB%E7%BA%BF%7C%20SCH%5B%22%E8%B0%83%E5%BA%A6%E8%BF%9B%E7%A8%8B%EF%BC%9A%E4%BA%8B%E4%BB%B6%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20SCH%20--%3E%7C%22%E5%87%86%E5%85%A5%20%2B%20%E5%89%8D%E7%BC%80%E6%A0%91%E5%A4%8D%E7%94%A8%22%7C%20SB%5B%22%E8%B0%83%E5%BA%A6%E6%89%B9%22%5D%0A%20%20SB%20--%3E%7C%E6%94%B6%E7%AA%84%7C%20MB%5B%22%E6%89%A7%E8%A1%8C%E6%89%B9%22%5D%0A%20%20MB%20--%3E%7C%E7%BF%BB%E8%AF%91%7C%20FB%5B%22%E5%86%85%E6%A0%B8%E6%89%B9%22%5D%0A%20%20FB%20--%3E%20RUN%5B%22TP%20%E6%89%A7%E8%A1%8C%E5%99%A8%20%2B%20%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%90%8E%E7%AB%AF%22%5D%0A%20%20RUN%20--%3E%20KV%5B%22%E4%B8%A4%E6%B1%A0%EF%BC%9A%E8%AF%B7%E6%B1%82%E6%A7%BD%E4%BD%8D%E7%B4%A2%E5%BC%95%20%2F%20KV%20%E5%BC%A0%E9%87%8F%E6%B1%A0%22%5D%0A%20%20RUN%20--%3E%7C%E7%BB%93%E6%9E%9C%7C%20SCH%0A%20%20SCH%20--%3E%20DTOK%5B%22%E5%8F%8D%E5%88%86%E8%AF%8D%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%7C%E6%B5%81%E5%BC%8F%7C%20HTTP%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"调度策略里的缓存感知项按「最长可复用前缀优先」排序等待请求：这条排序逻辑就写在调度器的策略文件里，读源码时先把策略函数找出来，比顺着调用栈翻更快。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"三个化身分化的原因是决策与执行分属不同进程：调度批在调度进程里被组出来，执行批是跨进程消息的字面内容，内核批才接触张量。接口在边界处收窄，执行侧因此不必知道排队、复用与统计；投机解码、数据并行这些特性改动大多落在执行视图与内核视图，调度语义不动。前缀树插在准入处而不是执行处，是这套分层的第二个红利：复用与否在组批时就已定价，同一步内新旧请求可以被一视同仁地排进批——这正是「程序级复用」落到调度器里的位置。",-1)),(e(),n(o,null,{default:B(()=>[r(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E6%96%B0%E8%AF%B7%E6%B1%82%EF%BC%9A%E5%85%B1%E4%BA%AB%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%20%2B%20%E8%87%AA%E5%B8%A6%E9%97%AE%E9%A2%98%22%5D%20--%3E%20MATCH%5B%22%E6%9F%A5%E5%89%8D%E7%BC%80%E6%A0%91%EF%BC%9A%E5%8C%B9%E9%85%8D%E6%9C%80%E9%95%BF%E5%85%AC%E5%85%B1%E5%89%8D%E7%BC%80%22%5D%0A%20%20MATCH%20--%3E%7C%22%E5%91%BD%E4%B8%AD%208K%20%E5%85%B1%E4%BA%AB%E5%89%8D%E7%BC%80%22%7C%20REF%5B%22%E6%A7%BD%E4%BD%8D%E7%B4%A2%E5%BC%95%E7%9B%B4%E6%8E%A5%E6%8C%87%E5%90%91%E6%97%A7%20KV%22%5D%0A%20%20MATCH%20--%3E%7C%22%E6%9C%AA%E5%91%BD%E4%B8%AD%E9%83%A8%E5%88%86%22%7C%20NEW%5B%22%E5%8F%AA%E9%9C%80%E8%AE%A1%E7%AE%97%E8%87%AA%E5%B7%B1%E7%9A%84%E5%90%8E%E7%BC%80%20token%22%5D%0A%20%20REF%20--%3E%20ADMIT%5B%22%E5%87%86%E5%85%A5%E5%AE%9A%E4%BB%B7%E5%AE%8C%E6%88%90%EF%BC%9A%E6%96%B0%E6%97%A7%E8%AF%B7%E6%B1%82%E5%90%8C%E6%89%B9%E5%8F%AF%E6%8E%92%22%5D%0A%20%20NEW%20--%3E%20ADMIT%0A%20%20ADMIT%20--%3E%20EXEC%5B%22%E6%89%A7%E8%A1%8C%E6%89%B9%E5%8F%AA%E5%B8%A6%E5%89%8D%E7%BC%80%E9%95%BF%E5%BA%A6%E4%B8%8E%20KV%20%E7%B4%A2%E5%BC%95%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">可以把它想象成分批入库：调度批是带全套单据的整箱货，执行批是撕掉单据只剩货本身，内核批是按货架码好的托盘。每过一道边界就剥一层包装，剥到最后一层只剩张量——所以越往里走的代码越「不知道」排队和复用这些事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>以仓库当时状态为准：前向模式的枚举、后端注册方式、重叠调度的开启方式都在演进，读的时候以一步迭代的三个批结构为锚，不背字段名。也不把外置路由器当成运行时内部件：多实例的路由、负载与前缀亲和在仓库之外的独立组件里，见 <a href="/llm/sglang-router">SGLang Router</a>。树的生长、淘汰与引用计数本课不重讲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SGLang 运行时按 HTTP、分词、调度、反分词分层成多进程，边界上是消息总线，不是函数调用。</li><li>一步迭代的锚点是三批收窄链：调度批、执行批、内核批，逐层丢元数据、逐层贴近张量。</li><li>KV 是两池一树：槽位索引池、张量池、前缀树索引，复用在准入时定价。</li><li>进程拆分换来调度循环不被 CPU 字符串工作打断，与 TGI 的前后端拆分同构。</li><li>读法：先找策略函数与三批结构，再沿执行批进后端；字段名以仓库当时状态为准。</li><li>出处：Zheng et al., <em>SGLang</em>, NeurIPS 2024 与 sgl-project/sglang 仓库，按源码结构整理。</li></ul>',5))])}const u=s(g,[["render",d]]);export{f as __pageData,u as default};
